return [
  { json: { portal: 'ZAP',       preco: 450000, bairro: 'Batel' } },
  { json: { portal: 'VivaReal',  preco: 520000, bairro: 'Água Verde' } },
  { json: { portal: 'OLX',       preco: 450000, bairro: 'Batel' } },
];

// Um item por (portal, bairro). O nó seguinte roda uma vez por item.
// Os filtros vão na URL: o portal corta 1.569 para 31 antes de mandar, em vez
// de baixarmos 12 páginas para jogar quase tudo fora depois.
const FILTRO = 'precoMaximo=950000&quartos=2,3,4&vagas=2,3,4&areaMinima=100';

const bairros = [
  'alto-da-rua-xv', 'alto-da-gloria', 'agua-verde',   // preferenciais
  'bigorrilho', 'batel', 'merces',                    // secundários
];

const portais = {
  vivareal: b =>
    `https://www.vivareal.com.br/venda/parana/curitiba/bairros/${b}/apartamento_residencial/?${FILTRO}`,

  // ZAP desligado de propósito: 28 dos 30 anúncios têm o MESMO @id do VivaReal
  // e nenhum é exclusivo. Dobra o tempo da rodada sem acrescentar imóvel.
  // zap: b => `https://www.zapimoveis.com.br/venda/apartamentos/pr+curitiba++${b}/?${FILTRO}`,
};

return bairros.flatMap(bairro =>
  Object.entries(portais).map(([portal, montaUrl]) => ({
    json: { portal, bairro, url: montaUrl(bairro) },
  }))
);

// Junta os anúncios novos num texto só. O nó do Telegram roda uma vez por item
// de entrada: sem agregar, 80 anúncios virariam 80 mensagens.
const itens = $input.all().map(i => i.json);
if (itens.length === 0) return [];          // nada novo: não manda nada

// Um nó anterior pode descartar campos sem erro nenhum (o Set em modo manual faz
// exatamente isso). Sem esta checagem, a mensagem sai bonita e escrita
// "undefined · R$ NaN", com todos os nós verdes.
const quebrados = itens.filter(o => o.preco == null || o.bairro == null || !o.url);
if (quebrados.length) {
  throw new Error(
    `${quebrados.length} de ${itens.length} itens sem preco/bairro/url — ` +
    `algum nó anterior descartou campos. Chaves recebidas: ${Object.keys(itens[0]).join(', ')}`
  );
}

const brl = v => 'R$ ' + Number(v).toLocaleString('pt-BR');
const prioridade = ['alto-da-rua-xv', 'alto-da-gloria', 'agua-verde'];
const peso = b => { const i = prioridade.indexOf(b); return i < 0 ? 9 : i; };

itens.sort((a, b) => peso(a.bairro) - peso(b.bairro) || a.preco - b.preco);

const linhas = itens.map(o =>
  `🏠 <b>${o.bairro}</b> · ${brl(o.preco)}\n` +
  `${o.quartos ?? '?'}q · ${o.vagas ?? '?'}v · ${o.area ?? '?'}m² · ${o.rua ?? ''}\n` +
  `${o.url}`
);

// O Telegram corta a mensagem em 4096 caracteres, então quebra antes disso.
const msgs = [];
let atual = `<b>${itens.length} anúncio(s) novo(s)</b>\n\n`;
for (const l of linhas) {
  if ((atual + l).length > 3500) { msgs.push(atual); atual = ''; }
  atual += l + '\n\n';
}
if (atual.trim()) msgs.push(atual);

return msgs.map(texto => ({ json: { texto } }));
